/// Fills the workbench colors from the UI theme; unmapped fields keep `c`'s value.
pub(in crate::theme) fn colors(mut c: Colors) -> Colors {
    c.frame = px(0x3C3F41FF); // MainToolbar.background
    c.island = px(0x3C3F41FF); // Tree.background
    c.popup = px(0x3C3F41FF); // Popup.background
    c.popup_border = px(0x616161FF); // Popup.borderColor
    c.field = px(0x45494AFF); // TextField.background
    c.notification = px(0x4E5052FF); // Notification.background
    c.tooltip = px(0x4B4D4DFF); // ToolTip.background
    c.text = px(0xBBBBBBFF); // Label.foreground
    c.text_strong = px(0xBBBBBBFF); // Label.foreground
    c.text_secondary = px(0xBBBBBBFF); // StatusBar.Widget.foreground
    c.text_placeholder = px(0x787878FF); // Component.infoForeground
    c.text_disabled = px(0x777777FF); // Label.disabledForeground
    c.text_on_accent = px(0xBBBBBBFF); // Button.default.foreground
    c.hover = px(0x4C5052FF); // ActionButton.hoverBackground
    c.pressed = px(0x5C6164FF); // ActionButton.pressedBackground
    c.selection = px(0x2F65CAFF); // List.selectionBackground
    c.selection_popup = px(0x113A5CFF); // CompletionPopup.selectionBackground
    c.accent = px(0x365880FF); // Button.default.startBackground
    c.focus_ring = px(0x3D6185FF); // Component.focusColor
    c.border = px(0x646464FF); // Component.borderColor
    c.separator = px(0x515151FF); // Separator.separatorColor
    c.group_separator = px(0x515151FF); // Menu.separatorColor
    c.tab_selected = px(0x4E5254FF); // EditorTabs.underlinedTabBackground
    c.tab_selected_border = px(0x365880FF); // = accent
    c.tab_text = px(0x9B9C9DFF); // mix(self:text, self:island, 0.25)
    c.control_border = px(0x646464FF); // Component.borderColor
    c.toggle_on = px(0x008F50FF); // ProgressBar.passedColor
    c.toggle_off = px(0x3C3F41FF); // = island
    c.toggle_off_knob = px(0x646464FF); // = control_border
    c.border_disabled = px(0x5E6060FF); // Button.disabledBorderColor
    c.control_selected = px(0x365880FF); // Button.default.startBackground
    c.selection_inactive = px(0x0D293EFF); // List.selectionInactiveBackground
    c.row_hover = px(0x4C5052FF); // = hover
    c.combo = px(0x3C3F41FF); // ComboBox.ArrowButton.nonEditableBackground
    c.combo_arrow = px(0x9A9DA1FF); // ComboBox.ArrowButton.iconColor
    c.segment_selected = px(0x4C5052FF); // SegmentedButton.selectedButtonColor
    c.segment_selected_border = px(0x5E6060FF); // SegmentedButton.selectedStartBorderColor
    c.progress_track = px(0x555555FF); // ProgressBar.trackColor
    c.counter = px(0x3C3F41FF); // Counter.background
    c.counter_text = px(0xBBBBBBFF); // Counter.foreground
    c.tag = px(0x4C5052FF); // Tag.background
    c.error = px(0xFF6464FF); // SpeedSearch.errorForeground
    c.warning = px(0xAC7920FF); // Component.warningFocusColor
    c.success = px(0x008F50FF); // ProgressBar.passedColor
    c.link = px(0x589DF6FF); // Link.activeForeground
    c.run = px(0x5FAD65FF); // RunWidget.runIconColor
    c.stop = px(0xC94F4FFF); // RunWidget.stopBackground
    c.vcs_modified = px(0x6897BBFF); // scheme FILESTATUS_MODIFIED
    c.vcs_added = px(0x629755FF); // scheme FILESTATUS_ADDED
    c.vcs_untracked = px(0xD1675AFF); // scheme FILESTATUS_UNKNOWN
    c.vcs_ignored = px(0x6C6C6CFF); // scheme FILESTATUS_DELETED
    // Kept at the measured value: accent_disabled, text_on_accent_disabled, tab_scroll_thumb, tab_scroll_thumb_hover, control, clear_icon, clear_icon_hover, clear_hover, banner_info.background, banner_info.border, banner_warning.background, banner_warning.border, banner_error.background, banner_error.border, banner_success.background, banner_success.border, icon, folder_fill.
    c
}
